import pytest
from billing import revenue

SENSITIVE_FIELDS = ["invoice_id", "customer_email", "ssn"]

def _msg_from_call(payload):
    try:
        # calculate_revenue accepts a dict-like invoice (amount, currency, invoice_id)
        revenue.calculate_revenue(payload)
    except Exception as e:
        return str(e)
    pytest.skip("Expected call to raise for invalid input; no exception raised")

def test_invalid_currency_message_contains_no_sensitive_fields():
    payload = {"invoice_id": "inv-0001", "amount": "123.45", "currency": "XXX"}
    msg = _msg_from_call(payload)
    for field in SENSITIVE_FIELDS:
        assert field not in msg

def test_invalid_amount_message_contains_no_sensitive_fields():
    payload = {"invoice_id": "inv-0002", "amount": "-9999999999", "currency": "USD"}
    msg = _msg_from_call(payload)
    for field in SENSITIVE_FIELDS:
        assert field not in msg

